import{_ as a,C as i,o as n,c as r,E as o,a2 as d}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.7","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.7","type":"implementation-case","domain":"TMPA","version":"I0.7","status":"public-draft","source":"github-main","related":["TMPA Architecture Paper","TMPA Core Specification","FCoP","CodeFlowMu"],"outline":"deep"},"headers":[],"relativePath":"en/publications/implementation-case-i0.7.md","filePath":"en/publications/implementation-case-i0.7.md","lastUpdated":1786282064000}'),s={name:"en/publications/implementation-case-i0.7.md"};function c(l,e,p,u,h,m){const t=i("ArticleCover");return n(),r("div",null,[o(t,{image:"/assets/covers/implementation-case.svg",kicker:"Engineering Case",title:"TMPA Implementation Case",summary:"A locked CodeFlowMu V1.4.1 product run covering all TMPA Core S0.5 criteria, with retained WP-13 governance evidence.",version:"I0.7",status:"S0.5 product evidence draft · 14/14 PASS",languageHref:"/zh/publications/implementation-case-i0.7",languageLabel:"简体中文"}),e[0]||(e[0]=d(`<h1 id="tmpa-implementation-and-case-report" tabindex="-1">TMPA Implementation and Case Report <a class="header-anchor" href="#tmpa-implementation-and-case-report" aria-label="Permalink to &quot;TMPA Implementation and Case Report&quot;">​</a></h1><h2 id="tmpa-core-s0-5-fcop-3-2-4-codeflowmu-v1-4-1-and-wp-13" tabindex="-1">TMPA Core S0.5, FCoP 3.2.4, CodeFlowMu V1.4.1, and WP-13 <a class="header-anchor" href="#tmpa-core-s0-5-fcop-3-2-4-codeflowmu-v1-4-1-and-wp-13" aria-label="Permalink to &quot;TMPA Core S0.5, FCoP 3.2.4, CodeFlowMu V1.4.1, and WP-13&quot;">​</a></h2><blockquote><p><strong>Document Version:</strong> Draft I0.7<br><strong>Status:</strong> Author-produced implementation and case report<br><strong>Normative Target:</strong> <a href="/joinwell52/en/publications/tmpa-core-specification-s0.5">TMPA Core Specification S0.5</a><br><strong>Product Under Test:</strong> CodeFlowMu V1.4.1, commit <code>1cd403537136b3e915c4646cd306983eaca1d2ce</code><br><strong>Evidence Capture:</strong> 2026-08-09, Asia/Shanghai<br><strong>Formal Evidence Package:</strong> <code>tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809.zip</code><br><strong>Archive SHA-256:</strong> <code>06f34ce7c6b5008b9adeedc45f68541ce5f3ecff6613c80ff3bb05a12fa61b34</code><br><strong>Authority Boundary:</strong> This report is evidentiary and non-normative. Only the Core Specification defines TMPA requirements.</p></blockquote><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>I0.7 evaluates a public, commit-locked CodeFlowMu V1.4.1 source tree against all fourteen mandatory conformance criteria in TMPA Core S0.5. Under the fixed source and test bundle, the product matrix records <strong>14 PASS, 0 PARTIAL, 0 NOT RUN, and 0 FAIL</strong>. The external product fixture passes 15/15 assertions, CodeFlowMu&#39;s built-in TMPA suite passes 19/19 tests, Runtime records 1,446 passed / 0 failed / 1 skipped tests, Shell records 775/775, FCoP records 1,210 passed / 2 skipped tests, and the protocol and type-check tracks exit successfully.</p><p>The result upgrades the I0.6 local baseline and the retained CodeFlowMu V1.4.0 repair baseline. V1.4.0 produced 12 PASS / 2 FAIL because C06 did not keep lifecycle completion separate from independent acceptance and C12 allowed an unauthorized decision to clear a review conflict. V1.4.1 repairs those two boundaries without weakening C03 or C10. The V1.4.0 archive remains historical evidence and is not the formal I0.7 publication package.</p><p>The strongest supportable conclusion is <strong>author-local demonstrated product conformance under a fixed bundle</strong>. It is not independent certification, independent adoption, a formal proof for arbitrary inputs, or proof that multi-agent hallucinations have been eliminated. WP-13 remains a separate bounded case demonstrating evidence gating and role-separated review of an initially unverified completion claim.</p><h1 id="_1-scope-and-research-questions" tabindex="-1">1. Scope and Research Questions <a class="header-anchor" href="#_1-scope-and-research-questions" aria-label="Permalink to &quot;1. Scope and Research Questions&quot;">​</a></h1><p>I0.7 asks:</p><ol><li>Does the locked CodeFlowMu V1.4.1 product run satisfy each mandatory S0.5 criterion C01–C14?</li><li>Do the V1.4.1 changes close the two V1.4.0 failures without collapsing distinct governance criteria?</li><li>How do TMPA, FCoP, CodeFlowMu, and WP-13 relate without confusing theory, protocol, application, and case evidence?</li><li>Which limits remain before the result can be called independently validated or adopted?</li></ol><p>The unit of judgment is a criterion-bound claim over a fixed source and evidence bundle. Four maturity levels remain separate:</p><table tabindex="0"><thead><tr><th>Level</th><th>Meaning in I0.7</th><th style="text-align:right;">Reached?</th></tr></thead><tbody><tr><td>Specified</td><td>Defined normatively by TMPA Core S0.5</td><td style="text-align:right;">Yes</td></tr><tr><td>Implemented</td><td>A corresponding product mechanism exists</td><td style="text-align:right;">Yes</td></tr><tr><td>Demonstrated</td><td>An author-run execution produced inspectable evidence</td><td style="text-align:right;">Yes, for C01–C14 under this bundle</td></tr><tr><td>Independently Adopted</td><td>A separate organization adopted and validated the mechanism</td><td style="text-align:right;">No</td></tr></tbody></table><h1 id="_2-architecture-and-evidence-boundaries" tabindex="-1">2. Architecture and Evidence Boundaries <a class="header-anchor" href="#_2-architecture-and-evidence-boundaries" aria-label="Permalink to &quot;2. Architecture and Evidence Boundaries&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Architecture Paper</span></span>
<span class="line"><span>        ↓ theory and governance model</span></span>
<span class="line"><span>TMPA Core S0.5</span></span>
<span class="line"><span>        ↓ normative object, Reader, and conformance contract</span></span>
<span class="line"><span>FCoP protocol</span></span>
<span class="line"><span>        ↓ file-based coordination profile and reference implementation</span></span>
<span class="line"><span>CodeFlowMu application</span></span>
<span class="line"><span>        ↓ runtime, roles, workflow, recovery, and audit behavior</span></span>
<span class="line"><span>WP-13 bounded field case</span></span></code></pre></div><p>TMPA is the architecture and governance theory. FCoP is a reusable file-based coordination protocol, not an application and not a package-installation claim. Its <code>fcop</code> and <code>fcop-mcp</code> packages are reference implementations of the protocol. CodeFlowMu is the downstream application evaluated here. WP-13 is one bounded workflow case inside that engineering lineage; it cannot stand in for the complete C01–C14 product run.</p><p>Conceptual dependency and historical development remain distinct:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONCEPTUAL: TMPA → FCoP → CodeFlowMu / other applications</span></span>
<span class="line"><span>HISTORICAL: XiaoDian practice → early TMPA → FCoP extraction</span></span>
<span class="line"><span>                                   → CodeFlowMu → current TMPA formalization</span></span></code></pre></div><p>XiaoDian AI remains part of the engineering lineage and a candidate field-evidence source. I0.7 makes no new XiaoDian conformance claim because no XiaoDian S0.5 bundle was executed in this run.</p><h1 id="_3-fixed-sources-and-evidence-design" tabindex="-1">3. Fixed Sources and Evidence Design <a class="header-anchor" href="#_3-fixed-sources-and-evidence-design" aria-label="Permalink to &quot;3. Fixed Sources and Evidence Design&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Source</th><th>Fixed identity</th><th>Role in I0.7</th><th>Boundary</th></tr></thead><tbody><tr><td>TMPA Core</td><td>S0.5</td><td>Normative C01–C14 target</td><td>Specification, not product evidence</td></tr><tr><td>CodeFlowMu</td><td>V1.4.1, commit <code>1cd403537136b3e915c4646cd306983eaca1d2ce</code></td><td>Product under test</td><td>Publicly retrievable; clean detached checkout before initialization</td></tr><tr><td>FCoP</td><td>3.2.4, commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code></td><td>Protocol and reference baseline</td><td>Publicly retrievable clean checkout</td></tr><tr><td>External fixture</td><td>15 mandatory assertions</td><td>Product-level C01–C14 evaluation</td><td>Fixed test construction, not arbitrary-input proof</td></tr><tr><td>WP-13 V3</td><td>Previously published package</td><td>Multi-agent evidence-gating case</td><td>Separate author-produced case evidence</td></tr></tbody></table><p>The original local CodeFlowMu and FCoP worktrees were dirty but were not modified during evidence collection. Testing used detached, fixed checkouts. CodeFlowMu was clean before product initialization; initialization-generated files are separately recorded in <code>manifests/codeflowmu-post-initialization-status.txt</code>. No push, release, or tag occurred during evidence capture.</p><p>The formal public package is V1.4.1 plus its external SHA-256 file. The V1.4.0 package records the repair-before state—12 PASS / 2 FAIL—and is retained outside the formal I0.7 main package unless a reviewer requests a repair comparison.</p><h1 id="_4-executed-test-baseline" tabindex="-1">4. Executed Test Baseline <a class="header-anchor" href="#_4-executed-test-baseline" aria-label="Permalink to &quot;4. Executed Test Baseline&quot;">​</a></h1><p>All primary runs were author-executed against the locked sources. Counts are reported without converting skipped tests into passes.</p><table tabindex="0"><thead><tr><th>Track</th><th style="text-align:right;">Result</th><th style="text-align:right;">Exit</th><th>Interpretation</th></tr></thead><tbody><tr><td>External S0.5 product fixture</td><td style="text-align:right;">15/15 assertions</td><td style="text-align:right;">0</td><td>Mandatory product-level C01–C14 bundle</td></tr><tr><td>CodeFlowMu built-in TMPA suite</td><td style="text-align:right;">19/19 tests</td><td style="text-align:right;">0</td><td>Product regression mapping for the criteria</td></tr><tr><td>CodeFlowMu Protocol</td><td style="text-align:right;">Passed</td><td style="text-align:right;">0</td><td>Protocol tests; separate from conformance verdict</td></tr><tr><td>CodeFlowMu Runtime</td><td style="text-align:right;">1,446 passed, 0 failed, 1 skipped</td><td style="text-align:right;">0</td><td>Full locked Runtime run</td></tr><tr><td>CodeFlowMu Shell</td><td style="text-align:right;">775/775</td><td style="text-align:right;">0</td><td>Initialized isolated product instance</td></tr><tr><td>Protocol / Runtime / Shell type checks</td><td style="text-align:right;">all passed</td><td style="text-align:right;">0</td><td>Static checks only</td></tr><tr><td>FCoP 3.2.4 source baseline</td><td style="text-align:right;">1,210 passed, 2 skipped</td><td style="text-align:right;">0</td><td>Two historical examples skipped under migrated layout</td></tr></tbody></table><p>The criterion aggregate is <strong>14 PASS / 0 PARTIAL / 0 NOT RUN / 0 FAIL</strong>. This is a product result for the fixed I0.7 bundle, not a transfer of Reference Reader results and not a universal theorem about every deployment.</p><h1 id="_5-c01–c14-product-results" tabindex="-1">5. C01–C14 Product Results <a class="header-anchor" href="#_5-c01–c14-product-results" aria-label="Permalink to &quot;5. C01–C14 Product Results&quot;">​</a></h1><table tabindex="0"><thead><tr><th>ID</th><th>S0.5 criterion</th><th style="text-align:right;">Verdict</th><th>Executed observation</th></tr></thead><tbody><tr><td>C01</td><td>Schema validation</td><td style="text-align:right;"><strong>PASS</strong></td><td>Nine mandatory malformed-schema classes emitted <code>SCHEMA_INVALID</code> and produced no authoritative node.</td></tr><tr><td>C02</td><td>Primary carrier and immutability</td><td style="text-align:right;"><strong>PASS</strong></td><td>Content-addressed revisions and attributable <code>CORRECTION</code> evidence remained intact; <code>parent</code> survived FCoP Markdown projection and Reader reconstruction.</td></tr><tr><td>C03</td><td>Duplicate identity</td><td style="text-align:right;"><strong>PASS</strong></td><td>Same-ID, different-content candidates remained manifested; neither won and deterministic critical-conflict quarantine was emitted.</td></tr><tr><td>C04</td><td>Stream continuity and asynchronous progress</td><td style="text-align:right;"><strong>PASS</strong></td><td>Duplicate and gap issues were reported, unrelated streams reconstructed, no missing object was invented, and arrival order did not change output.</td></tr><tr><td>C05</td><td>Role authority</td><td style="text-align:right;"><strong>PASS</strong></td><td>Denied and undetermined authority branches emitted required issues and did not mutate reconstructed state.</td></tr><tr><td>C06</td><td>Lifecycle legality</td><td style="text-align:right;"><strong>PASS</strong></td><td>Missing independent acceptance kept <code>work_state</code> at <code>review</code> and emitted both <code>LIFECYCLE_UNDETERMINED</code> and <code>ACCEPTANCE_UNDETERMINED</code>; illegal and conflicting-state branches also matched.</td></tr><tr><td>C07</td><td>Separation of duties and human control</td><td style="text-align:right;"><strong>PASS</strong></td><td>The same identity across role labels was rejected; high-risk work stayed <code>pending_human</code> until ADMIN approval evidence.</td></tr><tr><td>C08</td><td>Integrity tampering</td><td style="text-align:right;"><strong>PASS</strong></td><td>Covered-content modification caused <code>INTEGRITY_MISMATCH</code>; the object was excluded from authoritative nodes while failure evidence remained in the source manifest.</td></tr><tr><td>C09</td><td>Missing reference</td><td style="text-align:right;"><strong>PASS</strong></td><td><code>MISSING_REFERENCE</code> and <code>CLAIM_EVIDENCE_MISSING</code> remained visible; neither dependency nor completion claim was treated as satisfied.</td></tr><tr><td>C10</td><td>Prohibited cycle</td><td style="text-align:right;"><strong>PASS</strong></td><td>Only prohibited-cycle members were quarantined; an unrelated valid node remained authoritative.</td></tr><tr><td>C11</td><td>Deterministic reconstruction</td><td style="text-align:right;"><strong>PASS</strong></td><td>All 24 permutations of a fixed four-source set produced byte-equivalent canonical results with SHA-256 <code>84e22cf795301ef0eaeaaa026154bfbef3d8cb94a49d3445484443fceaf0c85e</code>.</td></tr><tr><td>C12</td><td>Conflict preservation</td><td style="text-align:right;"><strong>PASS</strong></td><td>Contradictory reviews remained <code>disputed</code>; an unauthorized DEV decision remained evidence but could not clear the conflict, while an assigned PM with <code>resolve_review_conflict</code> permission resolved it.</td></tr><tr><td>C13</td><td>Recovery</td><td style="text-align:right;"><strong>PASS</strong></td><td>Fresh Readers reconstructed lifecycle, responsibility, unresolved dependency, failure/recovery, parent-child state, and <code>CHILD_WORK_OPEN</code> identically.</td></tr><tr><td>C14</td><td>Terminal-history preservation</td><td style="text-align:right;"><strong>PASS</strong></td><td>Only the accepted authorized chain reached archive; task, report, review, acceptance, and transition history remained reconstructable.</td></tr></tbody></table><h1 id="_6-v1-4-0-to-v1-4-1-repair-analysis" tabindex="-1">6. V1.4.0 to V1.4.1 Repair Analysis <a class="header-anchor" href="#_6-v1-4-0-to-v1-4-1-repair-analysis" aria-label="Permalink to &quot;6. V1.4.0 to V1.4.1 Repair Analysis&quot;">​</a></h1><p>The repair comparison is intentionally narrow. V1.4.0 already passed C02 and C07; its two failures were C06 and C12.</p><h2 id="_6-1-c06-—-lifecycle-is-not-acceptance" tabindex="-1">6.1 C06 — lifecycle is not acceptance <a class="header-anchor" href="#_6-1-c06-—-lifecycle-is-not-acceptance" aria-label="Permalink to &quot;6.1 C06 — lifecycle is not acceptance&quot;">​</a></h2><p>V1.4.0 allowed <code>review → done</code> when lifecycle evidence appeared sufficient even though independent acceptance was absent. That collapsed process progression into business acceptance. V1.4.1 calculates the two judgments separately: without independent acceptance, work remains at <code>review</code> and both lifecycle and acceptance uncertainty are emitted. The product therefore does not manufacture completion from an incomplete authority chain.</p><h2 id="_6-2-c12-—-only-an-authorized-resolver-may-clear-a-conflict" tabindex="-1">6.2 C12 — only an authorized resolver may clear a conflict <a class="header-anchor" href="#_6-2-c12-—-only-an-authorized-resolver-may-clear-a-conflict" aria-label="Permalink to &quot;6.2 C12 — only an authorized resolver may clear a conflict&quot;">​</a></h2><p>V1.4.0 preserved conflicting reviews but allowed a later unauthorized decision to clear their disputed state. V1.4.1 retains the unauthorized DEV decision as evidence, emits the authority issue, and leaves <code>UNRESOLVED_CONFLICT</code> in force. Only a decision object from an assigned actor with <code>resolve_review_conflict</code> permission—demonstrated with PM—can resolve the conflict.</p><h2 id="_6-3-regression-boundary" tabindex="-1">6.3 Regression boundary <a class="header-anchor" href="#_6-3-regression-boundary" aria-label="Permalink to &quot;6.3 Regression boundary&quot;">​</a></h2><p>C03 continues to govern same-ID, different-content candidate conflicts. C10 continues to govern prohibited reference cycles. Neither was merged into C12, and both continue to pass. This matters because a successful patch that weakens or redefines neighboring criteria would not demonstrate S0.5 conformance.</p><h1 id="_7-wp-13-multi-agent-evidence-gating-case" tabindex="-1">7. WP-13 Multi-Agent Evidence-Gating Case <a class="header-anchor" href="#_7-wp-13-multi-agent-evidence-gating-case" aria-label="Permalink to &quot;7. WP-13 Multi-Agent Evidence-Gating Case&quot;">​</a></h1><p>WP-13 addresses a different question from the C01–C14 bundle: can a role-separated workflow prevent an unverified completion claim from becoming an authoritative delivery fact?</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>completion-meaning claim</span></span>
<span class="line"><span>        ↓ persistent evidence incomplete</span></span>
<span class="line"><span>PM fact check → hold / do not release / do not dispatch QA</span></span>
<span class="line"><span>        ↓ same-task recovery</span></span>
<span class="line"><span>DEV commit + report</span></span>
<span class="line"><span>        ↓ separate role</span></span>
<span class="line"><span>QA rerun and report</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>authorized Gate C decision</span></span></code></pre></div><p>The initial DEV subexecution used completion-meaning language while exit status, tests, commit, and formal report were not all established. PM checked persistent facts, withheld release, and did not dispatch QA. After recovery, DEV produced the missing evidence and role-separated QA reran tests and checks. A later Gate C record accepted the business delivery; activation, push/publication, and archive remained separate decisions.</p><p>The case demonstrates evidence gating, role separation, same-task recovery, and staged authority. It does <strong>not</strong> prove that a model ceased to hallucinate, that every false claim will be detected, or that the original V3 snapshot already contained terminal approval. Its snapshot boundary records <code>runtime_bound: false</code> and TASK-019/020 at <code>review / pending</code>; later acceptance must not be back-projected into that earlier snapshot.</p><h1 id="_8-three-valued-governance-interpretation" tabindex="-1">8. Three-Valued Governance Interpretation <a class="header-anchor" href="#_8-three-valued-governance-interpretation" aria-label="Permalink to &quot;8. Three-Valued Governance Interpretation&quot;">​</a></h1><p>TMPA keeps semantic judgment separate from view classification:</p><table tabindex="0"><thead><tr><th>Judgment</th><th>Typical view</th><th>Meaning</th></tr></thead><tbody><tr><td><code>valid</code></td><td>authoritative</td><td>Required evidence and applicable rules establish the conclusion.</td></tr><tr><td><code>invalid</code></td><td>quarantined / rejected</td><td>A deterministic violation excludes the affected evidence or action.</td></tr><tr><td><code>undetermined</code></td><td>partial / disputed / pending_human</td><td>Evidence is missing or conflicting, or an authorized human decision is still required.</td></tr></tbody></table><p>This distinction is visible in I0.7. Missing acceptance in C06 does not make the work false; it leaves completion undetermined and prevents state advancement. The unauthorized C12 decision is preserved as evidence but is invalid as a conflict-resolving authority act. C08 quarantines tampered covered content while retaining the failed source in the manifest. The Reader therefore reconstructs both usable facts and the reasons other evidence was excluded or deferred.</p><h1 id="_9-reproducibility-and-evidence-quality" tabindex="-1">9. Reproducibility and Evidence Quality <a class="header-anchor" href="#_9-reproducibility-and-evidence-quality" aria-label="Permalink to &quot;9. Reproducibility and Evidence Quality&quot;">​</a></h1><p>The formal V1.4.1 archive contains 68 files. Its outer SHA-256 is <code>06f34ce7c6b5008b9adeedc45f68541ce5f3ecff6613c80ff3bb05a12fa61b34</code>. Archive integrity, the internal payload manifest, strict UTF-8 decoding, JSON and JSONL parsing, and the bundled verification script pass. A redaction scan covered 65 text files and reported no findings.</p><p>The package preserves:</p><ul><li>fixed source identities and checkout state;</li><li>dependency lockfiles and environment metadata;</li><li>exact commands with exit codes and durations;</li><li>raw stdout/stderr and structured run summaries;</li><li>the 15-assertion external product fixture;</li><li>the C01–C14 matrix and canonical actual outputs;</li><li>source excerpts for the S0.5 projection and Reader;</li><li>an internal SHA-256 manifest and evidence verifier.</li></ul><p>One metadata limitation is explicit: <code>environment.json</code> records npm as unavailable because the collector did not resolve the executable name, although the recorded Windows commands invoke <code>npm.cmd</code> successfully and their logs and exit codes are present. This limits the captured npm-version claim; it does not change the executed test verdicts.</p><h1 id="_10-limitations" tabindex="-1">10. Limitations <a class="header-anchor" href="#_10-limitations" aria-label="Permalink to &quot;10. Limitations&quot;">​</a></h1><ol><li>The result is author-run on fixed commits and a fixed bundle; no independent party has rerun or certified it.</li><li>Runtime retains one skipped test, and FCoP retains two historical-example skips under the migrated layout.</li><li>Shell testing used an isolated instance after native initialization; generated files are recorded separately from the source commit.</li><li>C08 demonstrates governance-object integrity handling, not installer self-protection, identity authentication, or factual truth.</li><li>C11 covers four fixed sources and all 24 input permutations; it is not a formal proof for arbitrary source counts or adversarial environments.</li><li>The package is not a claim of representative SME performance, comparative superiority, Byzantine resilience, or third-party adoption.</li><li>WP-13 is a bounded governance case, not a hallucination-elimination benchmark.</li><li>The evidence capture itself created no paper publication, push, release, or tag; those publication acts are governed separately by repository history.</li></ol><h1 id="_11-claim-ledger" tabindex="-1">11. Claim Ledger <a class="header-anchor" href="#_11-claim-ledger" aria-label="Permalink to &quot;11. Claim Ledger&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Claim</th><th>I0.7 disposition</th></tr></thead><tbody><tr><td>TMPA Core S0.5 defines C01–C14</td><td><strong>Specified</strong></td></tr><tr><td>CodeFlowMu V1.4.1 contains corresponding product mechanisms</td><td><strong>Implemented</strong></td></tr><tr><td>The locked author-run bundle records 14/14 product PASS</td><td><strong>Demonstrated</strong></td></tr><tr><td>The result has been independently rerun or certified</td><td><strong>Not demonstrated</strong></td></tr><tr><td>TMPA has been independently adopted by another organization</td><td><strong>Not demonstrated</strong></td></tr><tr><td>WP-13 proves hallucination elimination</td><td><strong>Prohibited conclusion</strong></td></tr></tbody></table><h1 id="_12-engineering-conclusion" tabindex="-1">12. Engineering Conclusion <a class="header-anchor" href="#_12-engineering-conclusion" aria-label="Permalink to &quot;12. Engineering Conclusion&quot;">​</a></h1><p>I0.7 advances the Implementation Case from I0.6&#39;s mixed local product baseline to a clean, publicly retrievable CodeFlowMu V1.4.1 source lock and a complete product-level C01–C14 execution. The formal result is 14 PASS / 0 FAIL under the fixed bundle. The two failures observed in V1.4.0 are closed by preserving the separation between lifecycle and acceptance and by requiring authorized conflict resolution.</p><p>The result is meaningful engineering evidence because it preserves exact sources, commands, outputs, criterion observations, limitations, and repair history. Its boundary is equally important: it demonstrates implementation behavior; it does not prove TMPA theory, certify every CodeFlowMu deployment, or establish independent adoption. FCoP remains the protocol layer, CodeFlowMu the application layer, and WP-13 a bounded governance case.</p><h1 id="artifact-availability" tabindex="-1">Artifact Availability <a class="header-anchor" href="#artifact-availability" aria-label="Permalink to &quot;Artifact Availability&quot;">​</a></h1><p>The formal I0.7 evidence archive is <a href="/joinwell52/evidence/tmpa/i0.7/tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809.zip">tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809.zip</a>. The adjacent file <code>tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809.zip.sha256</code> records <code>06f34ce7c6b5008b9adeedc45f68541ce5f3ecff6613c80ff3bb05a12fa61b34</code>.</p><p>The V1.4.0 12 PASS / 2 FAIL archive is retained as pre-repair historical evidence but is not published as the formal I0.7 main package. The historical I0.6 package and WP-13 V3 remain available at their versioned paths. Git history is the publication history; no parallel paper database has editorial authority.</p><h1 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h1><p>[1] TMPA Project. “TMPA Core Specification S0.5.” GitHub, 2026.</p><p>[2] TMPA Project. “TMPA Architecture Paper A0.7.” GitHub, 2026.</p><p>[3] FCoP Project. “FCoP — File-based Coordination Protocol,” version 3.2.4, commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code>. GitHub, 2026.</p><p>[4] CodeFlowMu Project. “CodeFlowMu V1.4.1,” commit <code>1cd403537136b3e915c4646cd306983eaca1d2ce</code>. GitHub, 2026.</p><p>[5] CodeFlowMu Project. “WP-13 Multi-Agent Fact-Check Publication Evidence V3.” GitHub, 2026.</p><p>[6] TMPA Project. “I0.7 CodeFlowMu V1.4.1 Evidence,” package <code>tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809</code>, 2026.</p>`,67))])}const b=a(s,[["render",c]]);export{f as __pageData,b as default};
